// Carriages drawn in a single, undistorted coordinate system.
const carriageNames=['Toa hành khách 01','Toa Hoa Phượng Đỏ','Toa bưu điện','Toa tranh Tết','Toa chở hàng','Toa Hành trình Di sản','Toa Hà Nội hai tầng','Toa SJourney','Toa cổ Đà Lạt','Đầu máy D19E'];
const carriageDescriptions=['Tìm hiểu cổ phục phù hợp với bạn','Thử mặc cổ phục','Tìm hiểu về các hoạt động Việt phục','Tìm hiểu về lịch sử Việt phục','Tìm hiểu về lịch sử Việt phục','Tìm hiểu về lịch sử Việt phục','Địa điểm nên chụp ảnh với cổ phục','Địa điểm nên chụp ảnh với cổ phục','Địa điểm nên chụp ảnh với cổ phục',''];
function renderTrain(){
const definitions=`<defs><linearGradient id="coachBlue" x2="0" y2="1"><stop stop-color="#135c9a"/><stop offset=".45" stop-color="#176ea9"/><stop offset="1" stop-color="#0b4c80"/></linearGradient><linearGradient id="metalRoof" x2="0" y2="1"><stop stop-color="#8b969c"/><stop offset=".26" stop-color="#d8dcda"/><stop offset=".55" stop-color="#b9c2c2"/><stop offset="1" stop-color="#7b8c92"/></linearGradient><linearGradient id="glass" x2="1" y2="1"><stop stop-color="#253a43"/><stop offset=".5" stop-color="#566c72"/><stop offset="1" stop-color="#142a35"/></linearGradient><linearGradient id="steel" x2="0" y2="1"><stop stop-color="#8f9693"/><stop offset=".45" stop-color="#3a4240"/><stop offset="1" stop-color="#171e20"/></linearGradient><linearGradient id="white" x2="0" y2="1"><stop stop-color="#f0f1e8"/><stop offset="1" stop-color="#c9cfc7"/></linearGradient><linearGradient id="mail" x2="0" y2="1"><stop stop-color="#edb439"/><stop offset="1" stop-color="#d4941b"/></linearGradient><linearGradient id="green" x2="0" y2="1"><stop stop-color="#4b6046"/><stop offset="1" stop-color="#283f2d"/></linearGradient><pattern id="gangway" width="4" height="8" patternUnits="userSpaceOnUse"><rect width="4" height="8" fill="#181f22"/><path d="M1 0v8" stroke="#3b4547"/></pattern></defs>`;
function bogie(x){return `<g transform="translate(${x} 294)"><rect x="-91" y="-4" width="182" height="9" rx="2" fill="#222a2b"/>${[-56,56].map(p=>`<g transform="translate(${p} 15)"><circle r="22" fill="url(#steel)" stroke="#222a2a" stroke-width="2"/><circle r="17.5" fill="#424a48" stroke="#777d77" stroke-width="1"/><circle r="11" fill="#303936"/><circle r="4" fill="#8d9287"/><path d="M-13 12q13 7 26 0" stroke="#a4a894" stroke-width="1" fill="none"/></g>`).join('')}<path d="M-84 3h168v12l-15 9H43l-12-7h-62l-12 7h-26l-15-9z" fill="#414b47" stroke="#6a746a" stroke-width="1.5"/><path d="M-73 6h146M-28 12h56" stroke="#8a9285" stroke-width="2"/>${[-30,30].map(p=>`<g transform="translate(${p} -5)"><rect x="-8" width="16" height="24" rx="4" fill="#1b2421"/>${[2,6,10,14,18].map(y=>`<path d="M-8 ${y}h16" stroke="#727e6d" stroke-width="2"/>`).join('')}</g>`).join('')}${[-56,56].map(p=>`<rect x="${p-8}" y="9" width="16" height="13" rx="2" fill="#596259" stroke="#929b89"/>`).join('')}<path d="M-82 26h164" stroke="#202b26" stroke-width="3"/></g>`}
function chassis(){return `<rect x="23" y="283" width="1054" height="9" fill="#27302d"/><path d="M28 293h1043" stroke="#5a6258" stroke-width="2"/><rect x="353" y="292" width="192" height="28" rx="3" fill="#343e38"/><path d="M362 300h173m-173 7h173" stroke="#687165" stroke-width="1"/><rect x="603" y="292" width="132" height="22" rx="2" fill="#242f2b"/>${bogie(220)}${bogie(887)}`}
function roof(){return `<path d="M18 74V62q0-30 31-30h1002q31 0 31 30v12z" fill="url(#metalRoof)" stroke="#6e7e84"/><path d="M49 36h1000M25 62h1053" stroke="#e1e5de" opacity=".4"/>${[155,350,545,740,935].map(p=>`<g transform="translate(${p} 24)"><path d="M-18 7l5-8h27l5 8z" fill="#9aa8ac" stroke="#6f7c80"/><path d="M-12 0h25" stroke="#d9ded9"/></g>`).join('')}<rect x="427" y="19" width="110" height="11" rx="3" fill="#8a999d" stroke="#637479"/><path d="M438 23h87m-87 4h87" stroke="#c1cacc" stroke-width="1"/>`}
function windowAt(x,width=68,frame='#162d3b',curtain='#c8c3a6',y=96,height=106){return `<g transform="translate(${x} ${y})"><rect width="${width}" height="${height}" rx="7" fill="${frame}"/><rect x="4" y="4" width="${width-8}" height="${height-8}" rx="4" fill="url(#glass)"/><path d="M6 7h14l-6 ${height-14}H6zm${width-24} 0h17v${height-14}h-9z" fill="${curtain}" opacity=".45"/><path d="M6 ${height*.57}h${width-12}" stroke="#a4b4b0" stroke-width="2"/><path class="window-shine" d="M25 6l-13 ${height-13}h8L34 6z" fill="#d3e5e5" opacity=".12"/><path d="M6 5h${width-12}" stroke="#c0ccbd" opacity=".55"/></g>`}
function doors(color){return [55,989].map(p=>`<g transform="translate(${p} 81)"><rect width="55" height="198" rx="2" fill="${color}" stroke="#b9c7bf" stroke-width="1"/><rect x="12" y="13" width="31" height="67" rx="5" fill="#182e3c" stroke="#a8b8b5" stroke-width="2"/><rect x="17" y="18" width="21" height="57" rx="3" fill="url(#glass)"/><path d="M43 93h10" stroke="#e0e0cf" stroke-width="3"/><path d="M4 111v70m47-70v70" stroke="#cad1c3" stroke-width="2"/><path d="M2 203h51m-49 6h47m-43 6h39" stroke="#85938b" stroke-width="3"/></g>`).join('')}
function connector(n){if(n===4||n===8)return `<path d="M1078 292h39" stroke="#27332e" stroke-width="8"/><path d="M1086 278q12 38 27 0" stroke="#323e37" stroke-width="3" fill="none"/>`;if(n===9)return '';return `<g><rect x="1083" y="100" width="34" height="175" rx="5" fill="url(#gangway)"/><path d="M1085 105v163m30-163v163" stroke="#59615d" stroke-width="2"/><path d="M1082 290h36" stroke="#202c28" stroke-width="7"/><path d="M1088 277q12 42 25 0" stroke="#232d2a" stroke-width="3" fill="none"/><path d="M1090 276l8 13m8-13-7 13" stroke="#a53f30" stroke-width="3"/></g>`}
function passenger(n,flower=false){const body=flower?'url(#green)':'url(#coachBlue)';let windows='';for(let i=0;i<10;i++)windows+=windowAt(151+i*79,68,flower?'#823d37':'#172e3c',flower?'#c2bc8c':'#b9c7bc');return `${chassis()}<rect x="18" y="70" width="1064" height="215" rx="6" fill="${body}" stroke="#334e50"/>${roof()}<path d="M19 65h1062" stroke="${flower?'#eef0dc':'#bc3229'}" stroke-width="5"/><rect x="19" y="70" width="1062" height="10" fill="#e3e8df"/>${flower?`<path d="M130 79h839l-20 122q-420 31-797 0z" fill="#e5e4d6"/>`:''}${windows}<rect x="19" y="221" width="1062" height="64" fill="${flower?'url(#green)':'url(#white)'}"/>${flower?`<path d="M133 208q420 35 837 0" stroke="#e9e8d8" stroke-width="6" fill="none"/>${Array.from({length:47},(_,i)=>`<path d="M${130+i*18} 237l12 7-12 7m4-14 12 7-12 7" stroke="#869650" stroke-width="1.4" fill="none" opacity=".7"/>`).join('')}<rect x="19" y="257" width="1062" height="28" fill="#9a3e37"/>`:`<path d="M19 234h1062" stroke="#c6322b" stroke-width="6"/>`}${doors(flower?'#344e34':'#145b93')}<text x="548" y="${flower?276:266}" font-family="Arial,sans-serif" font-size="15" font-weight="bold" text-anchor="middle" fill="${flower?'#e0c77c':'#195b8b'}">${flower?'ĐƯỜNG SẮT VIỆT NAM · VIETNAM RAILWAYS':'ĐƯỜNG SẮT VIỆT NAM'}</text><text x="134" y="277" font-family="Arial" font-size="9" fill="${flower?'#dcc884':'#265e84'}">VNR · A${31501+n}</text><rect x="966" y="143" width="15" height="21" rx="1" fill="#ebeadb"/><text x="974" y="158" font-family="Arial" font-size="12" text-anchor="middle" fill="#a6332f">${n+1}</text>${flower?`<ellipse cx="956" cy="113" rx="21" ry="11" fill="none" stroke="#c0b871"/><text x="956" y="115" font-size="4.5" text-anchor="middle" fill="#d2c27e">HOA PHƯỢNG ĐỎ</text>`:''}<path d="M120 83v194m859-194v194" stroke="#dbe3d1" opacity=".2"/>`}
function mail(){return `${chassis()}<rect x="18" y="70" width="1064" height="215" rx="6" fill="url(#mail)"/>${roof()}<path d="M19 77h1062" stroke="#f1d58c" stroke-width="3"/><path d="M18 70h232l72 215H18z" fill="url(#white)"/><path d="M19 271h1062" stroke="#185c98" stroke-width="8"/><rect x="435" y="92" width="122" height="171" fill="#c3881b" stroke="#90641d" stroke-width="2"/><path d="M444 98v155m104-155v155" stroke="#e7bd5f" stroke-width="2"/><rect x="440" y="148" width="10" height="48" rx="2" fill="#343b30"/><path d="M436 270h118" stroke="#969c86" stroke-width="4"/>${[95,350,628,755].map(p=>`<rect x="${p}" y="110" width="40" height="17" rx="5" fill="#1d2d30"/>`).join('')}<rect x="881" y="128" width="66" height="66" rx="5" fill="#21322e" stroke="#a27925" stroke-width="3"/><rect x="1008" y="91" width="46" height="173" fill="#dfa325" stroke="#b38c3e"/><rect x="1019" y="107" width="23" height="38" rx="2" fill="#223932"/><path d="M1042 169h9" stroke="#d8d4ad" stroke-width="3"/><g fill="#df9f27"><path d="M115 151h64l-15 9h-64zm-18 16h68l-15 9H82zm-14 16h66l-15 9H69z"/><path d="M180 151l-20 41h20l20-41z"/></g><text x="143" y="216" text-anchor="middle" font-family="Arial" font-size="12" fill="#597e91">VIETNAM POST</text><text x="767" y="220" text-anchor="middle" font-family="Arial" font-size="24" letter-spacing="1" fill="#275782">BƯU ĐIỆN VIỆT NAM</text>`}
function freight(){let ribs='';for(let x=40;x<1060;x+=74)ribs+=`<rect x="${x}" y="65" width="8" height="215" fill="#344b36" stroke="#879276" stroke-width="1"/><path d="M${x+13} 94h55m-55 23h55m-55 23h55m-55 23h55m-55 23h55m-55 23h55m-55 23h55m-55 23h55" stroke="#718364" stroke-width="3" opacity=".65"/>`;return `${chassis()}<path d="M18 70l15-24h1034l15 24v215H18z" fill="url(#green)" stroke="#263d2c" stroke-width="2"/><path d="M33 46h1034l15 24H18z" fill="#7c8973"/><rect x="18" y="68" width="1064" height="12" fill="#65765a"/>${ribs}<rect x="445" y="82" width="214" height="188" fill="#3c573a" stroke="#233a2b" stroke-width="4"/>${Array.from({length:8},(_,i)=>`<path d="M452 ${98+i*22}h200" stroke="#72846a" stroke-width="3"/>`).join('')}<path d="M552 86v180" stroke="#283f2b" stroke-width="6"/><path d="M544 160v41m17-41v41" stroke="#9a9d77" stroke-width="3"/><path d="M444 77h217M441 272h222" stroke="#a6ab86" stroke-width="3"/><path d="M754 181h236l-27 15H729zm-34 27h244l-28 15H695zm-33 27h250l-30 15H664z" fill="#d4aa36" opacity=".9"/><text x="144" y="116" font-family="Arial" font-size="17" font-style="italic" font-weight="bold" fill="#e1e6d5">RATRACO</text><text x="148" y="155" font-family="Arial" font-size="13" fill="#d1b451">ĐƯỜNG SẮT VIỆT NAM</text><text x="154" y="176" font-family="Arial" font-size="11" fill="#d1b451">G 231402</text><text x="60" y="269" font-family="Arial" font-size="12" fill="#d1b451">231832</text><path d="M30 278h1038" stroke="#a99663" stroke-width="3"/><path d="M1018 118v165m14-165v165m-14-140h14m-14 25h14m-14 25h14m-14 25h14m-14 25h14m-14 25h14" stroke="#39402a" stroke-width="3"/>`}
// Each overlay sits on the matching painted door, so the dark entrance is
// revealed as its panel slides aside on hover (or keyboard focus).
function hoverPassengerDoor(x,y,w,h,color,trim,side,caption=''){
  const shift=side==='left' ? w*.92 : -w*.92;
  return `<g class="hover-door" transform="translate(${x} ${y})"><rect x="1" y="1" width="${w-2}" height="${h-2}" rx="2" fill="#172229" stroke="${trim}" stroke-width="2"/><path d="M5 ${h-13}h${w-10}m-${w-10} 5h${w-10}" stroke="#87948b" stroke-width="2"/><path d="M7 4v${h-26}m${w-14} -${h-26}v${h-26}" stroke="#536369" stroke-width="2"/><g class="hover-door__panel" style="--door-shift:${shift}px"><rect width="${w}" height="${h}" rx="2" fill="${color}" stroke="${trim}" stroke-width="1.5"/><rect x="${Math.round(w*.22)}" y="13" width="${Math.round(w*.56)}" height="${Math.min(67,Math.round(h*.39))}" rx="5" fill="#1b303a" stroke="${trim}" stroke-width="2"/><rect x="${Math.round(w*.28)}" y="18" width="${Math.round(w*.44)}" height="${Math.min(57,Math.round(h*.32))}" rx="3" fill="url(#glass)"/><path d="M${side==='left'?w-13:4} 94h9" stroke="#ddd8bb" stroke-width="3"/><path d="M5 ${h-67}v52m${w-10} -52v52" stroke="${trim}" stroke-width="2"/>${caption?`<text x="${w/2}" y="${h-17}" text-anchor="middle" font-family="Georgia,serif" font-size="8" fill="${trim}">${caption}</text>`:''}</g><path d="M0 ${h+5}h${w}m-3 5h${w-6}m-4 5h${w-8}" stroke="#929d8d" stroke-width="3"/></g>`;
}
function hoverFreightDoor(){
  const leaf=(x,direction)=>`<g class="hover-door__panel" style="--door-shift:${direction*103}px"><rect x="${x}" y="82" width="107" height="188" fill="#3c573a" stroke="#263d2b" stroke-width="3"/>${Array.from({length:8},(_,i)=>`<path d="M${x+5} ${98+i*22}h97" stroke="#778b70" stroke-width="3"/>`).join('')}<path d="M${x+(direction<0?96:10)} 160v41" stroke="#a0a387" stroke-width="4"/></g>`;
  return `<g class="hover-door"><rect x="446" y="83" width="212" height="187" fill="#151e1d" stroke="#9aa186" stroke-width="3"/><path d="M466 250h172M466 255h172" stroke="#788578" stroke-width="2"/>${leaf(445,-1)}${leaf(552,1)}<path d="M444 79h217M442 273h221" stroke="#a7ad8b" stroke-width="3"/></g>`;
}
function hoverMailDoor(){
  return `<g class="hover-door"><rect x="435" y="92" width="122" height="171" fill="#1a2528" stroke="#816a37" stroke-width="3"/><path d="M447 251h96m-96-5h96" stroke="#8b9180" stroke-width="2"/><g class="hover-door__panel" style="--door-shift:-113px"><rect x="435" y="92" width="122" height="171" fill="#c3881b" stroke="#90641d" stroke-width="2"/><path d="M444 98v155m104-155v155" stroke="#e7bd5f" stroke-width="2"/><rect x="440" y="148" width="10" height="48" rx="2" fill="#343b30"/></g><path d="M435 270h122" stroke="#969c86" stroke-width="4"/></g>`;
}
function hoverLocomotiveDoor(){
  return `<g class="hover-door"><rect x="787" y="78" width="69" height="151" fill="#17242d" stroke="#aeb7ac" stroke-width="2"/><path d="M793 219h57m-57-5h57" stroke="#788b86" stroke-width="2"/><g class="hover-door__panel" style="--door-shift:-63px"><rect x="787" y="78" width="69" height="151" fill="#396080" stroke="#aeb7ac" stroke-width="2"/><rect x="788" y="152" width="67" height="76" fill="#8c567c"/><path d="M788 152h67" stroke="#e2ddc5" stroke-width="6"/><rect x="802" y="91" width="39" height="43" rx="6" fill="url(#glass)" stroke="#adbab5" stroke-width="2"/><path d="M795 165h12" stroke="#c4c5b7" stroke-width="3"/></g><path d="M787 235h69m-66 8h63m-60 8h57" stroke="#849185" stroke-width="4"/></g>`;
}
function hoverDoors(n){
  switch(n){
    case 0: return hoverPassengerDoor(55,81,55,198,'#145b93','#bdccc2','left')+hoverPassengerDoor(989,81,55,198,'#145b93','#bdccc2','right');
    case 2: return hoverMailDoor()+hoverPassengerDoor(1008,91,46,173,'#dfa325','#dfc88b','right');
    case 1: return hoverPassengerDoor(55,81,55,198,'#344e34','#d1d8c0','left')+hoverPassengerDoor(989,81,55,198,'#344e34','#d1d8c0','right');
    case 3: return hoverPassengerDoor(49,83,47,196,'#e7a4b5','#634d39','left')+hoverPassengerDoor(1003,83,47,196,'#e7a4b5','#634d39','right');
    case 4: return hoverFreightDoor();
    case 5: return hoverPassengerDoor(55,82,53,195,'#703782','#dbb329','left')+hoverPassengerDoor(992,82,53,195,'#703782','#dbb329','right');
    case 6: return hoverPassengerDoor(55,82,53,195,'#e8d7b4','#6b5c47','left')+hoverPassengerDoor(992,82,53,195,'#e8d7b4','#6b5c47','right');
    case 7: return hoverPassengerDoor(57,89,53,188,'#672e31','#d8c29b','left','SJourney')+hoverPassengerDoor(991,89,53,188,'#672e31','#d8c29b','right','SJourney');
    case 8: return ''; // The timber platform's original gates animate in renderDalatCar.
    case 9: return hoverLocomotiveDoor();
    default: return '';
  }
}
function renderRightFacingLocomotive(){
  const shape=renderLocomotive().replace(/<text\b[^>]*>[\s\S]*?<\/text>/g,'');
  return `<g transform="translate(1100 0) scale(-1 1)">${shape}</g><g fill="#e9e7d7" text-anchor="middle" font-family="Arial,sans-serif"><text x="450" y="147" font-size="19" letter-spacing=".7">ĐƯỜNG SẮT VIỆT NAM</text></g><rect x="875" y="161" width="65" height="20" rx="2" fill="#243a4a" stroke="#c5a84d"/><text x="908" y="176" font-family="Arial" font-weight="bold" font-size="12" text-anchor="middle" fill="#dbc46c">D19E-946</text><text x="826" y="199" fill="#dfc76d" font-family="Arial" font-size="12">2</text>`;
}
const cars=[()=>passenger(0),()=>passenger(3,true),mail,renderTetCar,freight,renderHeritageCar,renderHanoiCar,renderJourneyCar,renderDalatCar,renderRightFacingLocomotive];
return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${cars.length*1100} 360" role="img" aria-label="Đoàn tàu đi từ trái qua phải, gồm các toa hành khách, Hoa Phượng Đỏ, bưu điện, tranh Tết, chở hàng, Hành trình Di sản, Hà Nội hai tầng, SJourney, cổ Đà Lạt và đầu máy">${definitions}${cars.map((render,n)=>`<g class="train-car" transform="translate(${n*1100} 0)" data-car-name="${carriageNames[n]}" tabindex="0" aria-label="${carriageNames[n]}${carriageDescriptions[n] ? `; ${carriageDescriptions[n]}` : ''}; rê chuột hoặc nhấn Tab để mở cửa"><g class="car-topic-label"><rect x="290" y="37" width="520" height="${carriageDescriptions[n] ? 29 : 20}" rx="3" fill="#172b2a" opacity=".82"/><text x="550" y="48" text-anchor="middle" font-family="Arial,sans-serif" font-size="11" font-weight="bold" letter-spacing=".7" fill="#f4ead0">${carriageNames[n]}</text>${carriageDescriptions[n] ? `<text x="550" y="60" text-anchor="middle" font-family="Arial,sans-serif" font-size="8.5" fill="#eadfbe">${carriageDescriptions[n]}</text>` : ''}</g>${render()}${hoverDoors(n)}${connector(n)}</g>`).join('')}</svg>`;
}
